import json
n=19
src=[[2,2,2,2],[2,0,0,0],[2,0,0,2],[2,0,2,2]]
grid=[[0]*n for _ in range(n)]
starts=[0,5,10,15]
for i in range(4):
  for j in range(4):
    if src[i][j] != 2: continue
    r0,c0=starts[i],starts[j]
    for a in range(4):
      for b in range(4):
        grid[r0+a][c0+b] = 8 if (a,b)==(i,j) else src[a][b]
assert len(grid)==19 and all(len(row)==19 for row in grid)
assert set(x for row in grid for x in row) <= {0,2,8}
print(json.dumps({'action':'submit','grid':grid},separators=(',',':')))

